package com.myaccessibilitymodule

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.AccessibilityServiceInfo
import android.content.Intent
import android.graphics.PixelFormat
import android.net.Uri
import android.os.Build
import android.provider.Settings
import android.view.Gravity
import android.view.View
import android.view.WindowManager
import android.widget.ImageView
import android.widget.Toast
import android.view.accessibility.AccessibilityEvent
import expo.modules.core.interfaces.services.EventEmitter
import expo.modules.settings.ExpoAccessibilityModule

class MyAccessibilityService : AccessibilityService() {

    companion object {
        var eventEmitter: EventEmitter? = null
    }

    private var bubbleView: View? = null
    private lateinit var windowManager: WindowManager

    override fun onServiceConnected() {
        super.onServiceConnected()

        val info = AccessibilityServiceInfo().apply {
            eventTypes = AccessibilityEvent.TYPE_VIEW_TEXT_SELECTION_CHANGED
            feedbackType = AccessibilityServiceInfo.FEEDBACK_ALL_MASK
            flags = AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS or AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS
        }

        serviceInfo = info
        windowManager = getSystemService(WINDOW_SERVICE) as WindowManager
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        if (event?.eventType == AccessibilityEvent.TYPE_VIEW_TEXT_SELECTION_CHANGED) {
            val selectedText = event.text?.joinToString(" ")?.trim()

            if (!selectedText.isNullOrEmpty()) {
                ExpoAccessibilityModule.lastSelectedText = selectedText
                showFloatingBubble()

                eventEmitter?.emit("onTextSelected", mapOf("text" to selectedText))
            }
        }
    }

    override fun onInterrupt() {
        removeFloatingBubble()
    }

    private fun showFloatingBubble() {
        // Prevent showing multiple bubbles
        if (bubbleView != null) return

        // Check permission
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M && !Settings.canDrawOverlays(this)) {
            val intent = Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:$packageName"))
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            startActivity(intent)
            return
        }

        bubbleView = ImageView(this).apply {
            setImageResource(android.R.drawable.ic_dialog_info) // Replace with your own bubble icon
            setOnClickListener {
                val selectedText = ExpoAccessibilityModule.lastSelectedText
                Toast.makeText(this@MyAccessibilityService, "Selected: $selectedText", Toast.LENGTH_SHORT).show()

                // Emit again to JS if needed
                eventEmitter?.emit("onTextSelected", mapOf("text" to selectedText))
                removeFloatingBubble()
            }
        }

        val params = WindowManager.LayoutParams(
            WindowManager.LayoutParams.WRAP_CONTENT,
            WindowManager.LayoutParams.WRAP_CONTENT,
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O)
                WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY
            else
                WindowManager.LayoutParams.TYPE_PHONE,
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,
            PixelFormat.TRANSLUCENT
        )

        params.gravity = Gravity.TOP or Gravity.START
        params.x = 100
        params.y = 300

        windowManager.addView(bubbleView, params)
    }

    private fun removeFloatingBubble() {
        if (bubbleView != null) {
            windowManager.removeView(bubbleView)
            bubbleView = null
        }
    }
}
